func runSchemaList(flags rootFlags) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	defer c.Close()

	ctx := context.Background()

	// Query: list all schemas from pg_namespace
	query := `
SELECT
  nspname as "Name",
  nspowner::regrole::text as "Owner",
  CASE
    WHEN nspname ~ '^pg_' THEN 'system'
    WHEN nspname ~ '^information_schema' THEN 'system'
    ELSE 'user'
  END as "Type",
  obj_description(oid, 'pg_namespace') as "Description"
FROM pg_namespace
ORDER BY
  CASE
    WHEN nspname ~ '^pg_' THEN 0
    WHEN nspname = 'information_schema' THEN 1
    ELSE 2
  END,
  nspname
`

	rows, err := c.Query(ctx, query)
	if err != nil {
		return apiErr("failed to list schemas: %v", err)
	}
	defer rows.Close()

	var schemas []map[string]interface{}
	for rows.Next() {
		var name, owner, schemaType, description interface{}
		if err := rows.Scan(&name, &owner, &schemaType, &description); err != nil {
			return apiErr("failed to scan schema row: %v", err)
		}
		schemas = append(schemas, map[string]interface{}{
			"Name":        name,
			"Owner":       owner,
			"Type":        schemaType,
			"Description": description,
		})
	}

	if err := rows.Err(); err != nil {
		return apiErr("error iterating schemas: %v", err)
	}

	if len(schemas) == 0 {
		fmt.Println("No schemas found.")
		return nil
	}

	return flags.outputResult(schemas)
}

