func runSchemaDescribe(flags rootFlags, schema string) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	defer c.Close()

	ctx := context.Background()

	// First, validate schema exists
	var schemaOID int
	err = c.QueryRow(ctx, "SELECT oid FROM pg_namespace WHERE nspname = $1", schema).Scan(&schemaOID)
	if err != nil {
		return notFoundErr("schema %q not found", schema)
	}

	// Query: list tables, views, sequences in schema
	query := `
SELECT
  c.relname as "Name",
  CASE
    WHEN c.relkind = 'r' THEN 'table'
    WHEN c.relkind = 'v' THEN 'view'
    WHEN c.relkind = 'm' THEN 'materialized view'
    WHEN c.relkind = 'S' THEN 'sequence'
    WHEN c.relkind = 'f' THEN 'foreign table'
    WHEN c.relkind = 'p' THEN 'partitioned table'
    ELSE 'other'
  END as "Type",
  pg_size_pretty(pg_total_relation_size(c.oid)) as "Size",
  CASE
    WHEN c.relpersistence = 't' THEN 'temporary'
    WHEN c.relpersistence = 'u' THEN 'unlogged'
    ELSE 'permanent'
  END as "Persistence",
  obj_description(c.oid, 'pg_class') as "Description"
FROM pg_class c
JOIN pg_namespace n ON c.relnamespace = n.oid
WHERE n.nspname = $1
  AND c.relkind IN ('r', 'v', 'm', 'S', 'f', 'p')
ORDER BY c.relname
`

	rows, err := c.Query(ctx, query, schema)
	if err != nil {
		return apiErr("failed to describe schema %q: %v", schema, err)
	}
	defer rows.Close()

	var objects []map[string]interface{}
	for rows.Next() {
		var name, objType, size, persistence, description interface{}
		if err := rows.Scan(&name, &objType, &size, &persistence, &description); err != nil {
			// Gracefully skip dropped objects (MVCC race)
			continue
		}
		objects = append(objects, map[string]interface{}{
			"Name":        name,
			"Type":        objType,
			"Size":        size,
			"Persistence": persistence,
			"Description": description,
		})
	}

	if err := rows.Err(); err != nil {
		return apiErr("error iterating objects: %v", err)
	}

	if len(objects) == 0 {
		fmt.Printf("No objects found in schema %q.\n", schema)
		return nil
	}

	return flags.outputResult(objects)
}

