func runSchemaInspect(flags rootFlags, tableRef string) error {
	c, err := flags.newClient()
	if err != nil {
		return err
	}
	defer c.Close()

	ctx := context.Background()

	// Parse schema.table
	parts := strings.Split(tableRef, ".")
	if len(parts) != 2 {
		return usageErr("table reference must be in format <schema>.<table>, got %q", tableRef)
	}
	schema, table := parts[0], parts[1]

	// Validate table exists
	var tableOID int
	err = c.QueryRow(ctx, `
SELECT c.oid FROM pg_class c
JOIN pg_namespace n ON c.relnamespace = n.oid
WHERE n.nspname = $1 AND c.relname = $2 AND c.relkind IN ('r', 'v', 'm', 'f', 'p')
`, schema, table).Scan(&tableOID)
	if err != nil {
		return notFoundErr("table %q not found in schema %q", table, schema)
	}

	// Get table info
	var relKind, relPersistence string
	var relDescription interface{}
	err = c.QueryRow(ctx, `
SELECT c.relkind, c.relpersistence, obj_description(c.oid, 'pg_class')
FROM pg_class c
WHERE c.oid = $1
`, tableOID).Scan(&relKind, &relPersistence, &relDescription)
	if err != nil {
		return apiErr("failed to get table info: %v", err)
	}

	// Determine table type
	tableType := "table"
	switch relKind {
	case "v":
		tableType = "view"
	case "m":
		tableType = "materialized view"
	case "f":
		tableType = "foreign table"
	case "p":
		tableType = "partitioned table"
	}

	var persistence string
	switch relPersistence {
	case "t":
		persistence = "temporary (session-local)"
	case "u":
		persistence = "unlogged (lost on crash)"
	default:
		persistence = "permanent"
	}

	// Get columns
	columnQuery := `
SELECT
  a.attname as column_name,
  pg_catalog.format_type(a.atttypid, a.atttypmod) as column_type,
  a.attnotnull as not_null,
  a.atthasdef as has_default,
  d.adsrc as default_value,
  a.attnum as position,
  obj_description(a.attrelid, 'pg_class') as col_description
FROM pg_attribute a
LEFT JOIN pg_attrdef d ON a.attrelid = d.adrelid AND a.attnum = d.adnum
WHERE a.attrelid = $1
  AND a.attnum > 0
  AND NOT a.attisdropped
ORDER BY a.attnum
`

	rows, err := c.Query(ctx, columnQuery, tableOID)
	if err != nil {
		return apiErr("failed to get columns: %v", err)
	}
	defer rows.Close()

	var columns []map[string]interface{}
	for rows.Next() {
		var name, colType string
		var notNull, hasDefault bool
		var defaultValue interface{}
		var position int
		var colDescription interface{}

		if err := rows.Scan(&name, &colType, &notNull, &hasDefault, &defaultValue, &position, &colDescription); err != nil {
			continue
		}

		nullability := "nullable"
		if notNull {
			nullability = "not null"
		}

		columns = append(columns, map[string]interface{}{
			"Name":      name,
			"Type":      colType,
			"Nullable":  nullability,
			"Default":   defaultValue,
			"Position":  position,
			"Desc":      colDescription,
		})
	}

	if err := rows.Err(); err != nil {
		return apiErr("error iterating columns: %v", err)
	}

	// Get indexes
	indexQuery := `
SELECT
  i.relname as index_name,
  ix.indisprimary as is_primary,
  ix.indisunique as is_unique,
  ix.indisvalid as is_valid,
  pg_get_indexdef(ix.indexrelid) as index_def
FROM pg_index ix
JOIN pg_class i ON i.oid = ix.indexrelid
WHERE ix.indrelid = $1
ORDER BY ix.indisprimary DESC, i.relname
`

	rows, err = c.Query(ctx, indexQuery, tableOID)
	if err != nil {
		return apiErr("failed to get indexes: %v", err)
	}
	defer rows.Close()

	var indexes []map[string]interface{}
	for rows.Next() {
		var name string
		var isPrimary, isUnique, isValid bool
		var indexDef string

		if err := rows.Scan(&name, &isPrimary, &isUnique, &isValid, &indexDef); err != nil {
			continue
		}

		indexType := "index"
		if isPrimary {
			indexType = "primary key"
		} else if isUnique {
			indexType = "unique"
		}

		validity := "valid"
		if !isValid {
			validity = "invalid"
		}

		indexes = append(indexes, map[string]interface{}{
			"Name":  name,
			"Type":  indexType,
			"Valid": validity,
		})
	}

	if err := rows.Err(); err != nil {
		return apiErr("error iterating indexes: %v", err)
	}

	// Get constraints
	constraintQuery := `
SELECT
  c.conname as constraint_name,
  CASE
    WHEN c.contype = 'p' THEN 'primary key'
    WHEN c.contype = 'u' THEN 'unique'
    WHEN c.contype = 'f' THEN 'foreign key'
    WHEN c.contype = 'c' THEN 'check'
    ELSE 'other'
  END as constraint_type,
  pg_get_constraintdef(c.oid) as constraint_def
FROM pg_constraint c
WHERE c.conrelid = $1
ORDER BY c.contype, c.conname
`

	rows, err = c.Query(ctx, constraintQuery, tableOID)
	if err != nil {
		return apiErr("failed to get constraints: %v", err)
	}
	defer rows.Close()

	var constraints []map[string]interface{}
	var foreignKeys []map[string]interface{}

	for rows.Next() {
		var name, constraintType, constraintDef string

		if err := rows.Scan(&name, &constraintType, &constraintDef); err != nil {
			continue
		}

		// For foreign keys, extract referenced table/column info
		if constraintType == "foreign key" {
			// Parse FK definition to extract referenced table
			refTableName := extractReferencedTable(constraintDef)
			foreignKeys = append(foreignKeys, map[string]interface{}{
				"Name":           name,
				"Type":           constraintType,
				"Definition":     constraintDef,
				"ReferencedTable": refTableName,
			})
		} else {
			constraints = append(constraints, map[string]interface{}{
				"Name":       name,
				"Type":       constraintType,
				"Definition": constraintDef,
			})
		}
	}

	if err := rows.Err(); err != nil {
		return apiErr("error iterating constraints: %v", err)
	}

	// Build result
	result := map[string]interface{}{
		"Schema":          schema,
		"Table":           table,
		"Type":            tableType,
		"Persistence":     persistence,
		"Description":     relDescription,
		"Columns":         columns,
		"Indexes":         indexes,
		"Constraints":     constraints,
		"ForeignKeys":     foreignKeys,
	}

	return flags.outputResult(result)
}

// extractReferencedTable extracts the referenced table name from a constraint definition
// e.g., "FOREIGN KEY (user_id) REFERENCES users(id)" -> "users"
func extractReferencedTable(constraintDef string) string {
	// Simple extraction: look for "REFERENCES table_name"
	idx := strings.Index(constraintDef, "REFERENCES")
	if idx == -1 {
		return ""
	}

	// Find the table name after REFERENCES
	rest := constraintDef[idx+len("REFERENCES"):]
	rest = strings.TrimSpace(rest)

	// Extract until we hit a '(' or space or end of string
	endIdx := strings.IndexAny(rest, " (")
	if endIdx == -1 {
		return rest
	}

	return rest[:endIdx]
}
